import 'package:flutter/material.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:shared_preferences/shared_preferences.dart';

// Firebase Options (Generated by FlutterFire CLI)
import 'firebase_options.dart';

// Home Page
import 'home_page.dart';

// All Pages (Folder: lib/pages/)
import 'pages/about_page.dart';
import 'pages/activity_page.dart';
import 'pages/bmi_page.dart';
import 'pages/feedback_page.dart';
import 'pages/food_guide_page.dart';
import 'pages/health_tips_page.dart';
import 'pages/hydration_page.dart';
import 'pages/login_page.dart';
import 'pages/meal_planning_page.dart';
import 'pages/profile_page.dart';
import 'pages/quiz_page.dart';
import 'pages/registration_page.dart';
import 'pages/sleep_page.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();

  try {
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,
    );
  } catch (e) {
    debugPrint('Firebase init note: $e');
  }

  runApp(const WelloraApp());
}

// ======================================================
// WELLORA MAIN APP & ROUTING TABLE
// ======================================================

class WelloraApp extends StatelessWidget {
  const WelloraApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      title: 'Wellora',
      theme: ThemeData(
        colorScheme: ColorScheme.fromSeed(
          seedColor: const Color(0xFF4CAF50),
        ),
        useMaterial3: true,
        scaffoldBackgroundColor: const Color(0xFFF9FBF9),
      ),
      home: const SplashPage(),
      // Named Routes
      routes: {
        '/login': (context) => const LoginPage(),
        '/registration': (context) => const RegistrationPage(),
        '/about': (context) => const AboutPage(),
        '/activity': (context) => const ActivityPage(),
        '/bmi': (context) => const BmiPage(),
        '/feedback': (context) => const FeedbackPage(),
        '/food_guide': (context) => const FoodGuidePage(),
        '/health_tips': (context) => const HealthTipsPage(),
        '/hydration': (context) => const HydrationPage(),
        '/meal_planning': (context) => const MealPlanningPage(),
        '/profile': (context) => FutureBuilder<SharedPreferences>(
          future: SharedPreferences.getInstance(),
          builder: (context, snapshot) {
            if (!snapshot.hasData) {
              return const Scaffold(
                body: Center(
                  child: CircularProgressIndicator(color: Color(0xFF4CAF50)),
                ),
              );
            }
            final prefs = snapshot.data!;
            final name = prefs.getString('user_name') ?? 'Tannya';
            final email = prefs.getString('user_email') ?? '';
            return ProfilePage(userName: name, userEmail: email);
          },
        ),
        '/quiz': (context) => const QuizPage(),
        '/sleep': (context) => const SleepPage(),
      },
    );
  }
}

// ======================================================
// SPLASH PAGE
// ======================================================

class SplashPage extends StatefulWidget {
  const SplashPage({super.key});

  @override
  State<SplashPage> createState() => _SplashPageState();
}

class _SplashPageState extends State<SplashPage> {
  @override
  void initState() {
    super.initState();
    _checkLoginSession();
  }

  Future<void> _checkLoginSession() async {
    await Future.delayed(const Duration(seconds: 2));

    SharedPreferences prefs = await SharedPreferences.getInstance();

    if (!mounted) return;

    bool isLoggedIn = prefs.getBool('is_logged_in') ?? false;
    String userName = prefs.getString('user_name') ?? '';
    String userEmail = prefs.getString('user_email') ?? '';

    if (isLoggedIn && userName.isNotEmpty) {
      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder: (context) => HomePage(
            userName: userName,
            userEmail: userEmail,
          ),
        ),
      );
    } else {
      Navigator.pushReplacementNamed(context, '/login');
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFE8F5E9),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Container(
              height: 100,
              width: 100,
              decoration: const BoxDecoration(
                color: Color(0xFF4CAF50),
                shape: BoxShape.circle,
              ),
              child: const Icon(
                Icons.favorite,
                color: Colors.white,
                size: 55,
              ),
            ),
            const SizedBox(height: 20),
            const Text(
              'Wellora',
              style: TextStyle(
                fontSize: 32,
                fontWeight: FontWeight.bold,
                color: Color(0xFF2E7D32),
              ),
            ),
            const SizedBox(height: 8),
            const Text(
              'Learn • Eat Well • Live Well',
              style: TextStyle(
                fontSize: 14,
                color: Colors.black54,
              ),
            ),
            const SizedBox(height: 25),
            const SizedBox(
              width: 30,
              height: 30,
              child: CircularProgressIndicator(
                strokeWidth: 3,
                color: Color(0xFF4CAF50),
              ),
            ),
          ],
        ),
      ),
    );
  }
}